{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "keep",
  "supportive_card_ids": ["C03", "C15", "C17", "C07", "C13", "C18", "C27", "C06", "C08", "C23", "C24"],
  "contradictory_card_ids": ["C16", "C20", "C22", "C26"],
  "prediction_basis_card_ids": ["C03", "C15", "C17", "C07", "C13", "C18", "C27", "C06", "C08", "C23", "C24"],
  "claims": [
    {
      "claim": "In patients with cirrhosis, bumetanide—a loop diuretic with an acidic sulfonamide/arylamine scaffold—had absolute oral bioavailability of 95% (1 mg oral vs IV, n=8), with an additional record reporting 95–100%; this is the closest same-condition, same-class transfer for the query.",
      "card_ids": ["C03", "C15", "C17"]
    },
    {
      "claim": "Tolfenamic acid in cirrhosis showed oral bioavailability of about 100% (100 mg p.o. vs i.v., AUC comparison), with additional patient-level values of 91%, 113%, and 126%, all far above the 20% threshold.",
      "card_ids": ["C07", "C13", "C18", "C27"]
    },
    {
      "claim": "Isradipine in cirrhosis had systemic availability of about 37% (36.9 ± 16.2%), and a reanalysis reported 0.28 ± 0.14 in cirrhotic patients without shunts; even the lowest cirrhosis record remains above 20%.",
      "card_ids": ["C06", "C08", "C23", "C24"]
    },
    {
      "claim": "The query's physicochemical prior (fully ionized, logD -0.84, TPSA 100) is not affirmative evidence of F < 20%; acidic, ionized drugs such as bumetanide and tolfenamic acid show high F in the same condition.",
      "card_ids": ["C03", "C15", "C07", "C13"]
    },
    {
      "claim": "New L3 oral AUC/Cmax records are not absolute-bioavailability measurements and mostly concern unrelated molecules (gliclazide, lumiracoxib, QMPB, ABT-751) or healthy-volunteer tolfenamic acid Cmax; they do not change the cirrhosis-based prediction.",
      "card_ids": ["C28", "C29", "C30", "C31", "C32", "C33", "C34", "C35", "C36", "C37", "C38", "C39"]
    },
    {
      "claim": "Low-F records in the broader set (KNI-272 syrup 15.7%, IQG-607 in mice ~4%, slow-dissolving isoniazid tablet) involve different molecules, species, or formulations and do not transfer to the query.",
      "card_ids": ["C16", "C20", "C22", "C26"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C32"]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C28", "C29", "C30", "C31", "C33", "C34", "C35", "C36", "C37", "C38", "C39"]
    }
  ],
  "evidence_gaps": [
    "No direct torasemide-in-cirrhosis bioavailability or AUC record is present in the supplied cards.",
    "L3 records are oral exposure measurements only; none reports absolute F for the query or for a cirrhosis condition.",
    "Query-specific permeability, solubility, and first-pass extraction are not experimentally measured; the low prior is physicochemical only.",
    "Cirrhosis severity and the query's dose/formulation are unspecified; transfer from bumetanide/tolfenamic acid/isradipine relies on structural and condition analogy.",
    "Some low-F records are from non-cirrhotic, non-human, or formulation-specific settings and cannot be quantitatively transferred."
  ],
  "decision_summary": "Predicted high (F >= 20%): all transferable cirrhosis-context records—bumetanide 95–100%, tolfenamic acid ~100% (91–126%), and isradipine 28–37%—are above threshold; new L3 oral exposure records are not absolute F and do not alter this. The physicochemical low prior is not affirmative evidence of F < 20%, and low-F records are from unrelated molecules, species, or formulations. Confidence remains high; revision kept."
}

